import{_ as a,c as n,o as t,ag as r}from"./chunks/framework.B-aGGnuW.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"installation/index.md","filePath":"installation/index.md","lastUpdated":1792149212000}'),i={name:"installation/index.md"};function o(s,e,d,c,l,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>This guide installs Arch Linux with ext4, NetworkManager, PipeWire and a desktop of your choice. The main path uses UEFI and KDE Plasma on Wayland. GRUB on BIOS and LVM on LUKS encryption are covered as alternatives.</p><p>Read the pages in sidebar order. Commands in the installation section run as root in the live ISO, then inside <code>arch-chroot</code> where indicated. After reboot, use your regular user and <code>sudo</code> for administrative commands. Replace example device names, usernames and UUIDs before running commands.</p><p>The partitioning examples describe a fresh installation. Back up existing data first. For dual boot, preserve the existing EFI system partition and other operating systems&#39; partitions; consult the <a href="https://wiki.archlinux.org/title/Dual_boot_with_Windows" target="_blank" rel="noreferrer">dual-boot documentation</a> before changing the layout.</p><h2 id="references-and-maintenance" tabindex="-1">References and maintenance <a class="header-anchor" href="#references-and-maintenance" aria-label="Permalink to &quot;References and maintenance&quot;">​</a></h2><p>Use the <a href="https://wiki.archlinux.org/title/Installation_guide" target="_blank" rel="noreferrer">ArchWiki installation guide</a> alongside these instructions. This guide includes personal choices and does not cover every hardware configuration.</p><p>Read <a href="https://archlinux.org/news/" target="_blank" rel="noreferrer">Arch Linux news</a> before upgrades: some changes require manual intervention. You can subscribe to <a href="https://lists.archlinux.org/mailman3/lists/arch-announce.lists.archlinux.org/" target="_blank" rel="noreferrer">arch-announce</a>.</p><p>Content reviewed on 16 October 2026 against upstream documentation and package listings. The revised installation paths have not yet been boot-tested in a VM.</p><p>The original guide was inspired by <a href="https://sourceforge.net/projects/ezarch/files/Project_Files/" target="_blank" rel="noreferrer">Ezarch</a>.</p>',9)])])}const m=a(i,[["render",o]]);export{p as __pageData,m as default};
